package com.bank.reportadapter;

import java.util.*;
import java.util.logging.*;

public class ToArrayDemo {
    private static final Logger log = Logger.getLogger("ReportAdapter");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> staff = List.of(new Employee("Rajesh"), new Employee("Priya"));
        ReportAdapterService service = new ReportAdapterService();

        Employee[] arr = service.toArray(staff);
        log.info(() -> "typed array length=" + arr.length + " first=" + arr[0].getName());
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final String name;
    Employee(String name) { this.name = name; }
    String getName() { return name; }
}

// ─── Would be in service/ReportAdapterService.java ───
class ReportAdapterService {
    Employee[] toArray(List<Employee> staff) {
        return staff.stream()
            .toArray(Employee[]::new);   // typed array (not Object[])
    }
}
